import { createServerFn } from '@tanstack/react-start';
import { getCookie,setCookie } from '@tanstack/react-start/server';
import { z } from 'zod';
import { planSchema,roleSchema,workflowPriority,permittedCategory,indiaTimestamp,nextCheckin,appointmentInputSchema } from './care-domain';
import { canStartLekhaMode, lekhaEligible } from './lekha-domain';
import { careCardSchema, cardText } from './care-card';
import type { Json } from '@/integrations/supabase/types';
const workspace='hackathon-demo';
async function hash(value:string){const bytes=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(value));return Array.from(new Uint8Array(bytes),x=>x.toString(16).padStart(2,'0')).join('');}
async function authorized(role?:string){const token=getCookie('nayuva_demo');if(!token)throw new Error('Open your demo dashboard again.');const {supabaseAdmin:db}=await import('@/integrations/supabase/client.server');const {data,error}=await db.from('demo_sessions').select('*').eq('token_hash',await hash(token)).gt('expires_at',new Date().toISOString()).single();if(error||!data||role&&data.role!==role)throw new Error('This action is not available for this demo account.');return {db,role:data.role,caregiverProfileId:data.caregiver_profile_id};}
function check(error:{message:string}|null){if(error)throw new Error('Your changes could not be saved. Please try again.');}
export const openDemo=createServerFn({method:'POST'}).inputValidator(z.union([roleSchema,z.object({role:roleSchema,profileId:z.string().uuid()})])).handler(async({data})=>{const role=typeof data==='string'?data:data.role;if(typeof data==='string'&&role==='caregiver'){const existing=await authorized('caregiver').catch(()=>null);if(existing)return {role};throw new Error('Select a caregiver profile to open your dashboard.');}const {supabaseAdmin:db}=await import('@/integrations/supabase/client.server');let profileId:string|null=null;if(role==='caregiver'){let q=db.from('care_profiles').select('id').eq('workspace',workspace);q=typeof data==='object'?q.eq('id',data.profileId):q.eq('caregiver_name','Meera Sharma').order('created_at',{ascending:true});const {data:profile,error}=await q.limit(1).single();check(error);if(!profile)throw new Error('Demo caregiver unavailable');profileId=profile.id;}const token=crypto.randomUUID()+crypto.randomUUID();const {error}=await db.from('demo_sessions').insert({token_hash:await hash(token),role,caregiver_profile_id:profileId,expires_at:new Date(Date.now()+86400000).toISOString()});check(error);setCookie('nayuva_demo',token,{httpOnly:true,sameSite:'lax',secure:process.env['NODE_ENV']==='production',path:'/',maxAge:86400});return {role};});
export const getCareData=createServerFn({method:'GET'}).handler(async()=>{const {db,role,caregiverProfileId}=await authorized();let q=db.from('care_profiles').select('*').eq('workspace',workspace).order('created_at',{ascending:false});if(role==='caregiver')q=q.eq('id',caregiverProfileId??'00000000-0000-0000-0000-000000000000');const {data:babies,error}=await q;check(error);const ids=(babies??[]).map(b=>b.id);const [a,h,n,e,f]=await Promise.all([db.from('care_appointments').select('*').in('baby_id',ids).order('starts_at'),db.from('health_cards').select('*').in('baby_id',ids).order('created_at',{ascending:false}),db.from('clinical_notes').select('*').in('baby_id',ids).order('created_at',{ascending:false}),db.from('care_events').select('*').in('baby_id',ids).order('created_at',{ascending:false}),db.from('care_facility').select('*').eq('workspace',workspace).single()]);[a,h,n,e,f].forEach(r=>check(r.error));const {data:demoProfiles}=await db.from('care_profiles').select('id,baby_name,caregiver_name').eq('workspace',workspace).order('created_at',{ascending:true});return {demoProfiles:role==='care-team'?demoProfiles??[]:[],babies:babies??[],appointments:a.data??[],cards:(h.data??[]).map(c=>role==='caregiver'?{...c,review_note:''}:c),notes:(n.data??[]).map(x=>role==='caregiver'?{...x,additional_note:''}:x),events:(e.data??[]).filter(x=>role==='care-team'||x.caregiver_visible),settings:f.data?.settings??{}};});
async function babyAccess(db:Awaited<ReturnType<typeof authorized>>['db'],id:string,role:string){const {data,error}=await db.from('care_profiles').select('*').eq('id',id).eq('workspace',workspace).single();if(error||!data)throw new Error('Baby profile unavailable');if(role==='caregiver'){const session=await authorized('caregiver');if(session.caregiverProfileId!==id)throw new Error('Baby profile unavailable');}return data;}
export const savePlan=createServerFn({method:'POST'}).inputValidator(z.object({id:z.string().uuid().optional(),plan:planSchema})).handler(async({data})=>{const {db}=await authorized('care-team');if(data.id)await babyAccess(db,data.id,'care-team');const clean={...data.plan,specialReasons:data.plan.specialCare==='Yes'?data.plan.specialReasons:[],medications:data.plan.takingMedication==='Yes'?data.plan.medications:[]};const {data:b,error}=await db.from('care_profiles').upsert({id:data.id??crypto.randomUUID(),workspace,baby_name:clean.babyName,caregiver_name:clean.caregiverName,plan:clean as Json}).select().single();check(error);if(!b)throw new Error('Unable to create care plan');if(!data.id&&clean.followupDate){const {data:f}=await db.from('care_facility').select('settings').eq('workspace',workspace).single();check((await db.from('care_appointments').insert({baby_id:b.id,starts_at:indiaTimestamp(clean.followupDate,clean.followupTime),reason:clean.followupReason,location:f?.settings??{}})).error);}check((await db.from('care_events').insert({baby_id:b.id,kind:'Care Plan',summary:data.id?'Care plan updated by Dr. Ananya Rao':'Care plan created by Dr. Ananya Rao'})).error);return b.id;});
export const submitCard=createServerFn({method:'POST'}).inputValidator(z.object({babyId:z.string().uuid(),category:z.string().max(100),quote:z.string().trim().min(1).max(3000),observation:z.enum(['Caregiver reported','Reduced','Not recorded','Clinician attention requested'])})).handler(async({data})=>{const {db,role}=await authorized('caregiver');const b=await babyAccess(db,data.babyId,role);const plan=b.plan as unknown as import('./care-domain').CarePlan;const {data:latest,error:latestError}=await db.from('health_cards').select('created_at').eq('baby_id',b.id).order('created_at',{ascending:false}).limit(1);check(latestError);const slot=nextCheckin(plan,b.created_at,latest?.[0]?.created_at);if(!slot.due)throw new Error('Your next scheduled check-in is not due yet.');if(!permittedCategory(plan.categories??[],data.category))throw new Error('This observation is not approved in the care plan.');check((await db.from('health_cards').insert({baby_id:b.id,category:data.category,quote:data.quote,observation:data.observation,priority:workflowPriority(data.observation),plan_snapshot:b.plan,caregiver_name:b.caregiver_name,scheduled_for:slot.scheduledFor})).error);check((await db.from('care_events').insert({baby_id:b.id,kind:'Home Update',summary:`${data.category}: ${data.observation}`})).error);return {ok:true};});
export const reviewCard=createServerFn({method:'POST'}).inputValidator(z.object({id:z.string().uuid(),note:z.string().max(3000)})).handler(async({data})=>{const {db}=await authorized('care-team');const {data:c}=await db.from('health_cards').select('*').eq('id',data.id).single();if(!c)throw new Error('Update unavailable');await babyAccess(db,c.baby_id,'care-team');check((await db.from('health_cards').update({reviewed:true,review_note:data.note}).eq('id',data.id)).error);check((await db.from('care_events').insert({baby_id:c.baby_id,kind:'Review',summary:'Care team reviewed a home update',caregiver_visible:true})).error);return {ok:true};});
export const createAppointment=createServerFn({method:'POST'}).inputValidator(appointmentInputSchema).handler(async({data})=>{
 const {db}=await authorized('care-team');await babyAccess(db,data.babyId,'care-team');
 const {data:f}=await db.from('care_facility').select('settings').eq('workspace',workspace).single();const base=(f?.settings??{}) as Record<string,Json>;
 const location=data.location?{...base,...data.location,mapsLink:data.location.mapsLink.startsWith('https://')?data.location.mapsLink:''}:base;
 const id=crypto.randomUUID();const starts=indiaTimestamp(data.date,data.time),ends=data.endTime?indiaTimestamp(data.date,data.endTime):null;
 check((await db.from('care_appointments').insert({id,baby_id:data.babyId,starts_at:starts,ends_at:ends,reason:data.reason,location:{...location,mode:data.mode}})).error);
 if(data.mode==='online'){
   // Native 1-on-1 WebRTC room: room_url stores an unguessable signaling channel issued only to authorized participants.
   check((await db.from('online_appointments').insert({appointment_id:id,room_name:`nv-${id}`,room_url:`rtc:${crypto.randomUUID()}`,status:'ready'})).error);
 }
 check((await db.from('care_events').insert({baby_id:data.babyId,kind:'Appointment',summary:`${data.mode==='online'?'Online':'In-person'} ${data.reason} scheduled for ${data.date} at ${data.time}`})).error);return {ok:true,id};
});
export const updateAppointment=createServerFn({method:'POST'}).inputValidator(z.object({id:z.string().uuid(),status:z.enum(['Confirmed','Reschedule requested','Reschedule approved','Reschedule declined','Completed','Cancelled']),preferredDate:z.string().regex(/^\d{4}-\d{2}-\d{2}$/).optional(),preferredTime:z.string().regex(/^\d{2}:\d{2}$/).optional(),note:z.string().max(300).optional()})).handler(async({data})=>{const {db,role}=await authorized();const {data:a}=await db.from('care_appointments').select('*').eq('id',data.id).single();if(!a)throw new Error('Appointment unavailable');await babyAccess(db,a.baby_id,role);if(role==='caregiver'&&!['Confirmed','Reschedule requested'].includes(data.status))throw new Error('Action unavailable');if(role==='care-team'&&data.status==='Reschedule requested')throw new Error('Action unavailable');if(['Completed','Cancelled'].includes(a.status))throw new Error('This appointment is already closed');
 if(data.status==='Reschedule approved'||data.status==='Reschedule declined'){
  const req=a.reschedule as {date?:string;time?:string}|null;if(a.status!=='Reschedule requested'||!req?.date||!req.time)throw new Error('There is no pending reschedule request');
  const patch:{status:string;reschedule:null;starts_at?:string;ends_at?:string}={status:'Scheduled',reschedule:null};
  if(data.status==='Reschedule approved'){const starts=indiaTimestamp(req.date,req.time);if(new Date(starts).getTime()<Date.now())throw new Error('The requested time has already passed');patch['starts_at']=starts;if(a.ends_at)patch['ends_at']=new Date(new Date(starts).getTime()+(new Date(a.ends_at).getTime()-new Date(a.starts_at).getTime())).toISOString();}
  check((await db.from('care_appointments').update(patch).eq('id',a.id)).error);check((await db.from('care_events').insert({baby_id:a.baby_id,kind:'Appointment',summary:data.status==='Reschedule approved'?`Reschedule approved for ${req.date} at ${req.time}`:'Reschedule request declined; original time kept'})).error);return {ok:true};
 }
 if(data.status==='Reschedule requested'){if(!data.preferredDate||!data.preferredTime)throw new Error('Choose your preferred date and time');if(new Date(indiaTimestamp(data.preferredDate,data.preferredTime)).getTime()<Date.now())throw new Error('Choose a future date and time');}
 check((await db.from('care_appointments').update({status:data.status,reschedule:data.status==='Reschedule requested'?{date:data.preferredDate,time:data.preferredTime,note:data.note?.trim()||''}:null}).eq('id',a.id)).error);check((await db.from('care_events').insert({baby_id:a.baby_id,kind:'Appointment',summary:`Appointment ${data.status.toLowerCase()}`})).error);return {ok:true};});
export const saveClinicalNote=createServerFn({method:'POST'}).inputValidator(z.object({appointmentId:z.string().uuid(),observations:z.string().min(1).max(5000),decision:z.string().min(1).max(5000),followUp:z.string().max(3000),additionalNote:z.string().max(3000)})).handler(async({data})=>{const {db}=await authorized('care-team');const {data:a}=await db.from('care_appointments').select('*').eq('id',data.appointmentId).single();if(!a||a.status!=='Completed')throw new Error('Complete the appointment before recording it');await babyAccess(db,a.baby_id,'care-team');check((await db.from('clinical_notes').insert({baby_id:a.baby_id,appointment_id:a.id,observations:data.observations,decision:data.decision,follow_up:data.followUp,additional_note:data.additionalNote})).error);check((await db.from('care_events').insert({baby_id:a.baby_id,kind:'Clinical Note',summary:'Clinical documentation saved to the care journey',caregiver_visible:false})).error);if(data.followUp)check((await db.from('care_events').insert({baby_id:a.baby_id,kind:'Follow-up',summary:data.followUp})).error);return {ok:true};});
export const saveSettings=createServerFn({method:'POST'}).inputValidator(z.object({facilityName:z.string().max(200),address:z.string().max(500),mapsLink:z.string().max(1000).refine(v=>!v||/^https:\/\//.test(v),'Use an https location link'),careTeamContact:z.string().max(30),emergencyContact:z.string().max(30),ambulanceNumber:z.string().max(30),afterHoursContact:z.string().max(30)})).handler(async({data})=>{const {db}=await authorized('care-team');check((await db.from('care_facility').upsert({workspace,settings:data})).error);return {ok:true};});

/** Public synthetic demo directory exposes names only, never care plans or contacts. */
export const listCaregiverDemos=createServerFn({method:'GET'}).handler(async()=>{const {supabaseAdmin:db}=await import('@/integrations/supabase/client.server');const {data,error}=await db.from('care_profiles').select('id,baby_name,caregiver_name').eq('workspace',workspace).order('created_at');check(error);return data??[];});

// Sutra reads and writes only within an authorized baby/audience scope.
export const getSutraHistory=createServerFn({method:'POST'}).inputValidator(z.object({babyId:z.string().uuid(),conversationId:z.string().uuid().optional()})).handler(async({data})=>{
 const session=await authorized(); await babyAccess(session.db,data.babyId,session.role);
 const {data:conversations,error}=await session.db.from('sutra_conversations').select('*').eq('baby_id',data.babyId).eq('workspace',workspace).eq('audience',session.role).order('updated_at',{ascending:false}).limit(100);check(error);
 const ids=(conversations??[]).map(c=>c.id);
 const previews=ids.length?await session.db.from('sutra_messages').select('conversation_id,content').in('conversation_id',ids).eq('role','assistant').order('created_at',{ascending:false}).limit(1000):{data:[],error:null};check(previews.error);
 const listed=(conversations??[]).map(c=>({...c,preview:previews.data?.find(m=>m.conversation_id===c.id)?.content.slice(0,180)??''}));
 if(!data.conversationId)return {conversations:listed,messages:[]};
 const conversation=conversations?.find(c=>c.id===data.conversationId); const {canReadSutraConversation}=await import('./sutra-domain');
 if(!conversation||!canReadSutraConversation(conversation,data.babyId,session.role))throw new Error('Conversation unavailable for this profile.');
 const result=await session.db.from('sutra_messages').select('*').eq('conversation_id',conversation.id).order('created_at').order('id');check(result.error);
 return {conversations:listed,messages:result.data??[]};
});
export const askSutra=createServerFn({method:'POST'}).inputValidator(z.object({babyId:z.string().uuid(),question:z.string().min(1).max(1500),conversationId:z.string().uuid().optional(),focus:z.array(z.string().max(100)).max(12),attachments:z.array(z.object({name:z.string().max(200),text:z.string().max(12000)})).max(4).default([])})).handler(async({data})=>{
 const session=await authorized(); const baby=await babyAccess(session.db,data.babyId,session.role); const db=session.db;
 let conversationId=data.conversationId; let history:{role:'user'|'assistant';content:string}[]=[];
 if(conversationId){const {data:c,error}=await db.from('sutra_conversations').select('*').eq('id',conversationId).single();check(error);const {canReadSutraConversation}=await import('./sutra-domain');if(!c||!canReadSutraConversation(c,baby.id,session.role))throw new Error('Conversation unavailable for this profile.'); const h=await db.from('sutra_messages').select('role,content').eq('conversation_id',conversationId).order('created_at',{ascending:false}).limit(12);check(h.error);history=(h.data??[]).reverse().map(m=>({role:m.role as 'user'|'assistant',content:m.content}));}
 const [e,c,n,a]=await Promise.all([db.from('care_events').select('*').eq('baby_id',baby.id).order('created_at'),db.from('health_cards').select('*').eq('baby_id',baby.id).order('created_at'),session.role==='care-team'?db.from('clinical_notes').select('*').eq('baby_id',baby.id):Promise.resolve({data:[],error:null}),db.from('care_appointments').select('*').eq('baby_id',baby.id).order('starts_at')]);[e,c,n,a].forEach(r=>check(r.error));
 const events=(e.data??[]).filter(x=>session.role==='care-team'||x.caregiver_visible);
 const refs:string[]=['p'+baby.id];const ref=(id:string)=>{refs.push(id);return 'R'+(refs.length-1);};
 const record=JSON.stringify({carePlan:{ref:'R0',baby:baby.baby_name,caregiver:baby.caregiver_name,plan:baby.plan},events:events.map(x=>({ref:ref('e'+x.id),when:x.created_at,kind:x.kind,summary:x.summary})),healthCards:(c.data??[]).map(x=>({ref:ref('c'+x.id),document:'Svara check-in',when:x.created_at,topic:x.category,observation:x.observation,structuredSummary:x.summary_text,reviewed:x.reviewed,...(session.role==='care-team'?{reviewNote:x.review_note}:{})})),appointments:(a.data??[]).map(x=>({ref:ref('a'+x.id),when:x.starts_at,reason:x.reason,status:x.status})),clinicalNotes:(n.data??[]).map((x:Record<string,unknown>)=>({ref:ref('n'+String(x['id'])),document:((a.data??[]).find(y=>y.id===x['appointment_id'])?.location as Record<string,unknown>|null)?.['mode']==='online'?'Online appointment summary':'In-person appointment summary',when:x['created_at'],observations:x['observations'],decision:x['decision'],followUp:x['follow_up']}))}).slice(0,24000);
 const {sutraGuidance,sutraReplyLanguage,sutraLanguageInstruction,splitSutraSources,formatSutraBody}=await import('./sutra-domain');
 const language=sutraReplyLanguage(data.question);const langRule=sutraLanguageInstruction(language);
 const focusRefs=data.focus.map(f=>refs.indexOf(f)).filter(i=>i>=0).map(i=>'R'+i);
 const system=`You are Sutra, Nayuva AI's care-journey assistant for ${session.role==='care-team'?'a clinician':'a caregiver'}. Answer ONLY from the authorized care record below. ${sutraGuidance}\n\n${langRule}\nCurrent time: ${new Date().toISOString()}. Do not assume a scheduled appointment happened.${focusRefs.length?` The person selected these records: ${focusRefs.join(', ')}.`:''}\nRECORD: ${record}`;
 const userContent=data.question+(data.attachments.length?'\nUnreviewed user-provided attachments (not verified records):\n'+data.attachments.map(f=>`${f.name}: ${f.text}`).join('\n'):'');
 const modelHistory=history.map(m=>({role:m.role,content:m.role==='assistant'?splitSutraSources(m.content).body:m.content}));
 const {sarvamChat,SarvamError}=await import('./sarvam.server');let answer:string;
 try{answer=await sarvamChat([{role:'system',content:system},...modelHistory,{role:'user',content:`${userContent}\n\n(${langRule} Use short paragraphs and bullet points where helpful. End with the SOURCES line if you used the record.)`}],{temperature:0.3});}catch(e){throw new Error(e instanceof SarvamError?e.message:'Sutra could not answer right now.');}
 if(!conversationId){const created=await db.from('sutra_conversations').insert({baby_id:baby.id,workspace,audience:session.role,title:data.question.slice(0,100)}).select('id').single();check(created.error);if(!created.data)throw new Error('Conversation could not be saved.');conversationId=created.data.id;}
 {const p=splitSutraSources(answer.replace(/<think>[\s\S]*?<\/think>/g,''));const used=p.sources.map(x=>{const m=/^R(\d+)$/.exec(x);return m?refs[Number(m[1])]:refs.find(v=>v===x||v.startsWith(x));}).filter((x):x is string=>!!x&&/^[cn]/.test(x));answer=formatSutraBody(p.body)+(used.length?`\n\n[[sources:${[...new Set(used)].join(',')}]]`:'');}
 const now=Date.now();check((await db.from('sutra_messages').insert([{conversation_id:conversationId,role:'user',content:userContent,created_at:new Date(now).toISOString()},{conversation_id:conversationId,role:'assistant',content:answer,created_at:new Date(now+1).toISOString()}])).error);
 check((await db.from('sutra_conversations').update({updated_at:new Date(now+1).toISOString()}).eq('id',conversationId)).error);
 return {answer,conversationId};
});

export const prepareSvaraSession=createServerFn({method:'POST'}).inputValidator(z.object({channel:z.enum(['website_voice','phone'])})).handler(async({data})=>{
 const session=await authorized('caregiver'); if(!session.caregiverProfileId)throw new Error('Choose your caregiver profile first.');
 const baby=await babyAccess(session.db,session.caregiverProfileId,'caregiver'); const db=session.db; const plan=baby.plan as unknown as import('./care-domain').CarePlan;
 const {data:cards,error:cardError}=await db.from('health_cards').select('created_at,category,quote,reviewed').eq('baby_id',baby.id).order('created_at',{ascending:false}).limit(12);check(cardError);
 // Svara is always available: a due slot reuses its scheduled time, otherwise the check-in is ad-hoc.
 const slot=nextCheckin(plan,baby.created_at,cards?.[0]?.created_at);const scheduledFor=slot.due?slot.scheduledFor:new Date().toISOString();
 const {data:questions,error:qError}=await db.from('question_bank').select('id,topic,first_wording,returning_wording,response_type,validation,version').eq('active',true).eq('approval_status','approved').in('topic',[...plan.categories,'Caregiver concerns']);check(qError);
 const {data:instructions,error:iError}=await db.from('followup_instructions').select('instruction,topic,expires_on').eq('baby_id',baby.id).eq('plan_version',baby.plan_version).eq('status','active');check(iError);
 const {data:existing,error:xError}=await db.from('checkin_sessions').select('*').eq('baby_id',baby.id).eq('scheduled_for',scheduledFor).maybeSingle();check(xError);
 let checkin=existing;
 if(!checkin){const {data:created,error}=await db.from('checkin_sessions').insert({baby_id:baby.id,caregiver_name:baby.caregiver_name,plan_version:baby.plan_version,plan_snapshot:baby.plan,scheduled_for:scheduledFor,channel:data.channel,status:'in_progress',started_at:new Date().toISOString(),question_ids:(questions??[]).map(q=>q.id),agent_version:'1'}).select().single();check(error);checkin=created;}
 if(!checkin)throw new Error('Check-in could not be created.');
 if(checkin.status==='submitted')throw new Error('This check-in has already been submitted.');
 if(['incomplete','scheduled','failed'].includes(checkin.status)){check((await db.from('checkin_sessions').update({status:'in_progress',channel:data.channel}).eq('id',checkin.id)).error);checkin={...checkin,status:'in_progress'};}
 const {buildSvaraVariables}=await import('./svara-context.server');const vars=await buildSvaraVariables(db as never,baby.id,checkin.id,{...(baby.plan as Record<string,unknown>),babyName:baby.baby_name});
 return {sessionId:checkin.id,profileId:baby.id,babyName:baby.baby_name,phone:checkin.destination_phone||plan.mobile,transcript:checkin.transcript,summary:checkin.summary,questions:questions??[],context:{baby_name:baby.baby_name,caregiver_name:baby.caregiver_name,check_in_id:checkin.id,check_in_status:checkin.status,gender:plan.sex,...vars},phoneAvailable:true,callStatus:checkin.call_status,phoneBlocker:''};
});
export const saveSvaraTranscript=createServerFn({method:'POST'}).inputValidator(z.object({sessionId:z.string().uuid(),lines:z.array(z.object({role:z.enum(['user','bot']),content:z.string().min(1).max(6000)})).max(200),interrupted:z.boolean().default(false)})).handler(async({data})=>{
 const auth=await authorized('caregiver');const {data:s,error}=await auth.db.from('checkin_sessions').select('*').eq('id',data.sessionId).eq('baby_id',auth.caregiverProfileId??'').single();check(error);if(!s||s.status==='submitted')throw new Error('Check-in unavailable.');
 check((await auth.db.from('checkin_sessions').update({transcript:data.lines as Json,status:data.interrupted?'incomplete':'in_progress'}).eq('id',s.id)).error);return {ok:true};
});
