 if(!res.ok||!attempt){const code=res.status===401||res.status===403?'auth_error':res.status===400||res.status===422?'invalid_request':res.status===402?'telephony_balance':res.status>=500?'provider_error':`http_${res.status}`;console.error('Sarvam outbound failed',res.status,text.slice(0,500));await auth.db.from('checkin_sessions').update({call_status:'failed',failure_code:code}).eq('id',s.id);throw new Error(code==='invalid_request'?'Sarvam rejected the call configuration. No call was placed.':code==='auth_error'?'Sarvam has not authorized phone calling for this configuration.':code==='telephony_balance'?'Phone calling is paused because the calling balance is insufficient.':'The call could not be placed right now. Please try again shortly.');}
